const CURATED_DETAILS = new Map(
  CURATED_COVERAGE.map((c) => [c.ticker, { website: c.website, ir: c.ir, founded: c.founded, description: c.description }]),
);

/** Website, IR site, founding year and one-line description for a covered company (server only). */
export function coverageDetails(ticker: string): CoverageDetails {
  const t = ticker.toUpperCase();
  return CURATED_DETAILS.get(t) ?? EXTRA_DETAILS[t] ?? {};
}
